class OperationsView extends StatefulWidget {
  const OperationsView({super.key});
  @override State<OperationsView> createState() => _OperationsViewState();
}
class _OperationsViewState extends State<OperationsView> {
  final search = TextEditingController();
  String filter = 'all';
  @override void dispose() { search.dispose(); super.dispose(); }
  @override Widget build(BuildContext context) {
    final app = context.watch<AppController>();
    final q = search.text.trim();
    final rows = app.operations.where((row) {
      final status = '${row['status'] ?? ''}'.toLowerCase();
      final hit = q.isEmpty || '${row['id'] ?? ''} ${row['phone'] ?? ''} ${row['service'] ?? row['packageName'] ?? ''}'.contains(q);
      final ok = filter == 'all' || (filter == 'success' && (status == 'success' || status == 'completed')) || (filter == 'pending' && (status == 'pending' || status == 'queued' || status == 'processing')) || (filter == 'failed' && (status == 'failed' || status == 'rejected'));
      return hit && ok;
    }).toList();
    return ScreenFrame(title: 'سجل العمليات', color: AppColors.burgundy, actions: [IconButton(onPressed: app.refreshWalletAndReports, icon: const Icon(Icons.refresh_rounded))], child: Column(children: [
      Container(width: double.infinity, color: const Color(0xFFFEF3C7), padding: const EdgeInsets.symmetric(horizontal: 13, vertical: 9), child: const Row(children: [Icon(Icons.cloud_done_outlined, color: AppColors.amber, size: 17), SizedBox(width: 7), Expanded(child: Text('يعرض السجل العمليات الحقيقية المسترجعة من خادم Django.', style: TextStyle(fontSize: 9.5, color: Color(0xFF92400E), fontWeight: FontWeight.w800)))])),
      Container(color: Colors.white, padding: const EdgeInsets.fromLTRB(12, 9, 12, 7), child: Column(children: [
        TextField(controller: search, onChanged: (_) => setState(() {}), decoration: const InputDecoration(prefixIcon: Icon(Icons.search_rounded), hintText: 'ابحث برقم الهاتف أو الخدمة أو رقم العملية...', filled: true, fillColor: Color(0xFFF1F5F9), border: InputBorder.none, isDense: true)),
        const SizedBox(height: 7),
        SingleChildScrollView(scrollDirection: Axis.horizontal, child: Row(children: [for (final e in const {'all': 'الكل', 'success': 'ناجحة', 'pending': 'قيد الانتظار', 'failed': 'فاشلة'}.entries) Padding(padding: const EdgeInsets.only(right: 6), child: ChoiceChip(selected: filter == e.key, label: Text(e.value, style: const TextStyle(fontSize: 9, fontWeight: FontWeight.w900)), selectedColor: AppColors.burgundy, labelStyle: TextStyle(color: filter == e.key ? Colors.white : const Color(0xFF0F172A)), onSelected: (_) => setState(() => filter = e.key)))])),
      ])),
      Expanded(child: RefreshIndicator(onRefresh: app.refreshWalletAndReports, child: ListView(padding: const EdgeInsets.all(12), children: [if (rows.isEmpty) const EmptyState(text: 'لا توجد عمليات مطابقة في السجل.', icon: Icons.receipt_long_outlined), for (final row in rows) RefOperationTile(operation: row, onTap: () => showDialog(context: context, builder: (_) => OperationDetailModal(operation: row)))])),
    ]));
  }
}

class OperationDetailModal extends StatelessWidget {
  const OperationDetailModal({super.key, required this.operation});
  final Map<String,dynamic> operation;
  @override Widget build(BuildContext context) {
    final status = '${operation['status'] ?? ''}'.toLowerCase();
    final success = status == 'success' || status == 'completed';
    return AlertDialog(
      shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(22)),
      title: Row(children: [Icon(success ? Icons.check_circle_rounded : Icons.info_outline_rounded, color: success ? AppColors.emerald : AppColors.amber), const SizedBox(width: 7), const Expanded(child: Text('تفاصيل العملية', style: TextStyle(fontWeight: FontWeight.w900)))]),
      content: Column(mainAxisSize: MainAxisSize.min, children: [for (final e in {'رقم العملية': '${operation['id'] ?? '-'}', 'الخدمة': '${operation['service'] ?? operation['packageName'] ?? '-'}', 'الهاتف': '${operation['phone'] ?? '-'}', 'المبلغ': '${operation['amount'] ?? 0} ${operation['currency'] ?? 'YER'}', 'الحالة': '${operation['status'] ?? '-'}', 'التاريخ': '${operation['created_at'] ?? operation['date'] ?? '-'}'}.entries) Padding(padding: const EdgeInsets.symmetric(vertical: 4), child: Row(mainAxisAlignment: MainAxisAlignment.spaceBetween, children: [Text(e.key, style: const TextStyle(fontSize: 9, color: AppColors.muted)), Flexible(child: Text(e.value, textAlign: TextAlign.left, style: const TextStyle(fontSize: 10, fontWeight: FontWeight.w900)))])), if (operation['result'] != null) Padding(padding: const EdgeInsets.only(top: 5), child: Text('${operation['result']}', textAlign: TextAlign.center, style: const TextStyle(fontSize: 9, color: AppColors.muted))) ]),
      actions: [TextButton(onPressed: () => Navigator.pop(context), child: const Text('إغلاق'))],
    );
  }
}

