class _SupportScreenState extends State<SupportScreen>{final input=TextEditingController();Map<String,dynamic>? data;bool busy=false;@override void initState(){super.initState();_load();}@override void dispose(){input.dispose();super.dispose();}Future<void>_load()async{try{data=await context.read<AppController>().api.support();}catch(_){}if(mounted)setState((){});}Future<void>_send()async{if(input.text.trim().isEmpty)return;setState(()=>busy=true);try{data=await context.read<AppController>().api.sendSupportMessage(input.text.trim());input.clear();await _load();}catch(e){if(mounted)ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text(e.toString())));}finally{if(mounted)setState(()=>busy=false);}}@override Widget build(BuildContext context){final conv=data?['conversation'];final raw=conv is Map?conv['messages']:null;final msgs=raw is List?raw.whereType<Map>().map((e)=>Map<String,dynamic>.from(e)).toList():<Map<String,dynamic>>[];return ScreenFrame(title:'التواصل مع الإدارة',color:const Color(0xFF475569),child:Column(children:[Expanded(child:msgs.isEmpty?const Center(child:Text('لا توجد رسائل بعد.',style:TextStyle(color:AppColors.muted))):ListView(padding:const EdgeInsets.all(12),children:[for(final m in msgs)Align(alignment:m['sender_role']=='customer'?Alignment.centerRight:Alignment.centerLeft,child:Container(margin:const EdgeInsets.only(bottom:7),padding:const EdgeInsets.all(10),decoration:BoxDecoration(color:m['sender_role']=='customer'?AppColors.burgundy:Colors.white,borderRadius:BorderRadius.circular(14),border:Border.all(color:AppColors.border)),child:Text('${m['body']??''}',style:TextStyle(fontSize:10,color:m['sender_role']=='customer'?Colors.white:const Color(0xFF0F172A))))) ])),SafeArea(child:Container(color:Colors.white,padding:const EdgeInsets.all(9),child:Row(children:[Expanded(child:TextField(controller:input,maxLines:3,decoration:const InputDecoration(hintText:'اكتب رسالتك...',isDense:true))),IconButton(onPressed:busy?null:_send,style:IconButton.styleFrom(backgroundColor:AppColors.burgundy,foregroundColor:Colors.white),icon:const Icon(Icons.send_rounded))])))]));}}

class AddressesScreen extends StatelessWidget{const AddressesScreen({super.key});@override Widget build(BuildContext context){final app=context.watch<AppController>();return ScreenFrame(title:'عناوين التوصيل',color:AppColors.blue,child:ListView(padding:const EdgeInsets.all(12),children:[if(app.addresses.isEmpty)const EmptyState(text:'لا توجد عناوين محفوظة.',icon:Icons.location_off_outlined),for(final a in app.addresses)PageCard(margin:const EdgeInsets.only(bottom:7),child:ListTile(contentPadding:EdgeInsets.zero,leading:const Icon(Icons.location_on_rounded,color:AppColors.blue),title:Text('${a['label']??a['name']??'عنوان'}',style:const TextStyle(fontSize:11,fontWeight:FontWeight.w900)),subtitle:Text('${a['address']??a['details']??a['city']??''}',style:const TextStyle(fontSize:9,color:AppColors.muted)),trailing:IconButton(onPressed:()=>_delete(context,a),icon:const Icon(Icons.delete_outline_rounded,color:Colors.red)))),const SizedBox(height:6),FilledButton.icon(onPressed:()=>_add(context),style:FilledButton.styleFrom(backgroundColor:AppColors.blue),icon:const Icon(Icons.add_location_alt_outlined),label:const Text('إضافة عنوان'))]));}
Future<void>_delete(BuildContext context,Map a)async{final id=int.tryParse('${a['id']??''}');if(id==null)return;try{await context.read<AppController>().api.deleteAddress(id);await context.read<AppController>().refreshAll();}catch(e){if(context.mounted)ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text(e.toString())));}}Future<void>_add(BuildContext context)async{final label=TextEditingController(),address=TextEditingController(),city=TextEditingController();await showDialog<void>(context:context,builder:(_)=>AlertDialog(title:const Text('إضافة عنوان'),content:Column(mainAxisSize:MainAxisSize.min,children:[TextField(controller:label,decoration:const InputDecoration(labelText:'اسم العنوان')),TextField(controller:address,decoration:const InputDecoration(labelText:'العنوان')),TextField(controller:city,keyboardType:TextInputType.number,decoration:const InputDecoration(labelText:'city_id'))]),actions:[TextButton(onPressed:()=>Navigator.pop(context),child:const Text('إلغاء')),FilledButton(onPressed:()async{try{await context.read<AppController>().api.createAddress({'label':label.text.trim(),'address':address.text.trim(),'city_id':int.tryParse(city.text.trim())});await context.read<AppController>().refreshAll();if(context.mounted)Navigator.pop(context);}catch(e){if(context.mounted)ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text(e.toString())));}},child:const Text('حفظ'))]));label.dispose();address.dispose();city.dispose();}}

